def gen(n):
    m=n//2
    a=[[0]*n for _ in range(n)]
    for r in range(n):
        for d in range(-m,m+1):
            c=m+d
            if r<=m and abs(d)==r:
                a[r][c]=2
            elif abs(d)<=r-2 and (d-r)%4==0:
                a[r][c]=1
    return a
for n in (5,7,13):
    print(n, gen(n))
print('test:', gen(17))
